 void authorized(AuthorizationResult r,long g){if(a.destroyed){busy=false;return;}String token=r.getAccessToken();if(token==null||token.isEmpty()){fail(new IOException("Google did not grant Drive access"));return;}a.getPreferences(0).edit().putBoolean("googleConnected",true).apply();a.io.execute(()->{try{if(g!=generation)return;transfer(token,g);}catch(Exception e){if(g==generation)fail(e);}finally{a.handler.post(()->busy=false);}});}
